SELECT r.id || ' — разошёлся с родителем ' || r.parent_task_id || ': не хватает ' || coalesce((SELECT string_agg(pc.check_id, ', ' ORDER BY pc.check_id) FROM project_task_check pc WHERE pc.project_id = r.project_id AND pc.task_id = r.parent_task_id AND pc.said_as = 'доказательство' AND NOT EXISTS (SELECT 1 FROM project_task_check rc WHERE rc.project_id = r.project_id AND rc.task_id = r.id AND rc.check_id = pc.check_id)), '—') || ', лишние ' || coalesce((SELECT string_agg(rc.check_id, ', ' ORDER BY rc.check_id) FROM project_task_check rc WHERE rc.project_id = r.project_id AND rc.task_id = r.id AND NOT EXISTS (SELECT 1 FROM project_task_check pc WHERE pc.project_id = r.project_id AND pc.task_id = r.parent_task_id AND pc.said_as = 'доказательство' AND pc.check_id = rc.check_id)), '—') || coalesce((SELECT '; ' || string_agg(d.task_id || ': `' || d.check_id || '` не засчитана: снята ' || d.words, '; ' ORDER BY d.task_id, d.check_id) FROM project_check_dropped d WHERE d.project_id = r.project_id AND d.task_id IN (r.id, r.parent_task_id)), '') AS detail FROM project_plan_tasks r WHERE r.project_id = $1 AND r.kind = 'red' AND (EXISTS (SELECT 1 FROM project_task_check pc WHERE pc.project_id = r.project_id AND pc.task_id = r.parent_task_id AND pc.said_as = 'доказательство' AND NOT EXISTS (SELECT 1 FROM project_task_check rc WHERE rc.project_id = r.project_id AND rc.task_id = r.id AND rc.check_id = pc.check_id)) OR EXISTS (SELECT 1 FROM project_task_check rc WHERE rc.project_id = r.project_id AND rc.task_id = r.id AND NOT EXISTS (SELECT 1 FROM project_task_check pc WHERE pc.project_id = r.project_id AND pc.task_id = r.parent_task_id AND pc.said_as = 'доказательство' AND pc.check_id = rc.check_id))) ORDER BY 1
